import{_ as t,o as l,c as n,j as e,a as r}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第103章 一块地","description":"","frontmatter":{},"headers":[],"relativePath":"第103章_一块地.md","filePath":"第103章_一块地.md"}'),o={name:"第103章_一块地.md"};function s(p,a,_,c,d,i){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"第103章-一块地",tabindex:"-1"},[r("第103章 一块地 "),e("a",{class:"header-anchor",href:"#第103章-一块地","aria-label":'Permalink to "第103章 一块地"'},"​")],-1),e("p",null,'那年秋天，她有一整个月没上线。我说的是那个游戏。我们大二那年开始在那款游戏里有一块地。这件事要从头讲一句。高一那年她带我进这个游戏。她说，跟着我。她说，你别出去，你出去就死。那时候我不会玩，我就在她后面站着。后来我们两个干了一件事。这个游戏里有一块可以自己盖东西的地。她开了一块，我开了一块。那两块地挨着。我们两个把它拼到一起。拼上去那天，她在语音里"啊"了一声。她说，成了。我说，什么成了。她说，你那个角跟我这个角，正好差一条边。她说，我把它挪一下，它就对上了。她说，你看，两个东西能对上，是很少的。那天我们把那块地拼起来了。从那以后那块地一直在。',-1),e("p",null,"那个游戏我后来不怎么玩了。但是那块地我不动。每年我们那个游戏会出一次季节的东西，有些会枯。高二那年冬天，她四十多天没上，她那半边地里的苗全枯了。她回来那天，站在那块地中间，什么也没讲。她后来只发了一句：我以为你还在。我说，我在。她说，你每天上来？我说，我不上来，我怕别人偷。她说，这个游戏没有偷东西的。我说，我知道。她说，那你还上。我说，我上去看一眼那块地，我今天就算上来过。她说，你这个人真的很怪。她说，你把一块地当成一个人在等。",-1),e("p",null,"那年十月，她一个月没上。那一个月里我照样每天上去一次。我上去我就站在中间。她那半边那个房子上有一个我给她修的漏雨的口子。那个口子是我那年四月修的，我用了很多游戏里很难得的一个料。修完她笑了一次。她说，你怎么连在游戏里都补屋顶。我说，你这个屋顶不补它就漏。她说，这里下雨不下雨是系统的。我说，我知道。她说，你知道你还补。我说，我补完我那天晚上睡得着。",-1),e("p",null,'十一月三号她上线了。她一上来，站在那块地上。她什么也没讲。我们在游戏里站着。这个游戏里两个人站着不说话，是很平常的。但是那天我们站着的时间很长。后来她打字。她说，你把那个屋顶又刷了一遍。我说，上个月刷的。她说，为什么。我说，它褪色。她说，没人看这个。我说，你看。她说，我不看。她说，我这一个月我一次也没进来。我说，我知道。她说，那你为什么还刷。我在那个游戏里站着。我打的是：因为我这边刷了，你回来的时候它是新的。她说，你回来的时候我这儿也是新的。我说，你哪儿新了。她说，我今天进来之前我洗了头。她说，我进来我这个头像是新的。她说，我们两个都新了。我说，那挺好。她说，你又"那挺好"。她说，你讲这三个字的时候你心里在难受。我说，我没有。她说，你有。她说，你那一个月里，你每天进来站多久。我说，不久。她说，多久。我说，四分钟。她说，你每天四分钟，一个月是一百二十分钟。她说，你今天跟我讲不久。我说，我不算这个。她说，你已经在算了。她说，你连你自己站多久都不好意思讲。她说，闻迟，你站这个地上，你是不是觉得你在替我看家。我说，我没有。她说，你有。她说，你要没有，你今天不会刷那个屋顶。她说，你刷它是因为你觉得我今天会回来。她说，你怕我回来发现这个屋子旧了，你就没理由再站在这儿了。我说，你今天讲了这些，明天你还上不。她说，我上。我说，那你明天自己看。她说，你现在不讲这些是为了让我明天自己看见。我说，是。她说，你看，你又把我这个月替你把家看了这个事，变成了一个我明天要承认的东西。她说，你这个人，你从来不逼我。她说，你只是把东西摆在那儿，让我明天自己走过来捡。她说，我不想去捡。我说，那你不捡。她说，我今天晚上不捡。她说，明天我可能捡。她说，你不要赌我明天。我说，我赌你明天。她说，你赌你明天，我明天就要为了赢你这个赌不做。她说，你看，我说明天可能捡，你现在就赢了我一次。',-1),e("p",null,'那天夜里我们在那块地上站了很久。她十一点五十下线。下线前她说了一句。她说，你把这个游戏留着。我说，我一直留着。她说，我不是说留账号。她说，我是说，我哪天不在了，你别把这块地拆了。她说，你拆了这块地，就没有两块拼在一起这个东西了。她说，这个世界上一共也没几块拼得上的。我说，我不拆。她说，你要答应得很慢。我说，我不拆。她说，你这次讲得对。她说，你刚才那句"我不拆"，你没有想。',-1),e("p",null,'十一月有一次，我在上线的时候看见地上有人。那个人我们不认识。他站在我修的那道矮墙旁边。他头上顶着一个公会的名字，我们这边的人。他在那儿干什么，我看了半天才看出来。他在采东西。我们那块地边上会长一种很普通的草，这个草谁都可以采。他采了得有一百根。我站在那里。我那时候可以直接说一句，你说这是我们的地。我说不出口。因为这块地上今天只有我一个人。我说了，他问我另一个人是谁。我说，我一个朋友。他说，哪个朋友。我站在那里，我答不上来。我答不上来我就拿不了这个地。这个地它写得是我的名字。可是它一半是她的。我拿什么去讲"一半是她的"这句话。我那天什么都没说。我下线以前，我把那面矮墙又刷了一遍。我把地边上那个名字改了一个字。我以前写的是一个很难看的三个字。那天我把它改成了两个字。我改完我看着那两个字坐了很久。这两个字不是她的名字。也不是我的。是我们两个那年在那个店里，她拿手指在桌上划了一下，她说这里以前应该有个东西。她说的是"这里"。那天夜里我把这块地改成了"这里"。',-1),e("p",null,"那天夜里我在那块地上站了很久。我在我们两块地中间那条缝上，修了一道矮墙。那道墙在这个游戏里没有任何用处。它挡不了怪，也存不了东西。我修它是因为那道缝每年都要重刷一次。修了墙，那道缝就在墙底下，它不用刷。我修完站在中间看了一会儿。我那天做了一件我这辈子的事：我把一个每天要重复的活，变成了一个不用说的东西。",-1)])])}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
